INSERT INTO articulo_conocimiento (id, titulo, problema, sintomas, causa, solucion, categoria_id, estado, verificado, fecha_creacion, fecha_actualizacion) VALUES
(1, 'Equipo sin acceso a internet por falla de DHCP', 'El equipo no obtiene dirección IP válida y no navega.', 'Ícono de red con advertencia; ipconfig muestra una IP 169.254.x.x; no hay acceso a internet ni a recursos internos.', 'El cliente DHCP no recibe respuesta del servidor (cable suelto, puerto de switch deshabilitado o ámbito DHCP agotado).', '1. Verificar cable y luces del puerto de red. 2. Ejecutar ipconfig /release y luego ipconfig /renew. 3. Si persiste, ejecutar netsh winsock reset y netsh int ip reset y reiniciar. 4. Validar con Redes que el puerto del switch esté activo y que el ámbito DHCP tenga direcciones libres.', 1, 'ACTIVO', TRUE, '2026-03-20 00:00:00', '2026-03-20 00:00:00'),
(2, 'Wi-Fi corporativo se desconecta de forma intermitente', 'La conexión inalámbrica se cae varias veces al día.', 'Pérdida de conexión de pocos segundos; videollamadas congeladas; el equipo cambia entre redes.', 'Controlador de la tarjeta inalámbrica desactualizado o ahorro de energía que apaga el adaptador; interferencia con red de invitados.', '1. Actualizar el controlador Wi-Fi desde el portal del fabricante. 2. En Administrador de dispositivos > adaptador > Administración de energía, desmarcar ''Permitir que el equipo apague este dispositivo''. 3. Olvidar la red de invitados y priorizar la red corporativa. 4. Si afecta a varios usuarios de la misma zona, escalar a Redes para revisar el punto de acceso.', 1, 'ACTIVO', TRUE, '2026-03-21 00:00:00', '2026-03-21 00:00:00'),
(3, 'Los nombres de dominio no resuelven (falla de DNS)', 'Se navega por IP pero no por nombre de sitio.', 'Mensaje DNS_PROBE_FINISHED_NXDOMAIN; ping a 8.8.8.8 responde pero ping a un dominio falla.', 'Servidores DNS mal configurados en el adaptador o caché DNS corrupta.', '1. Ejecutar ipconfig /flushdns. 2. Verificar que el adaptador use DNS automático (DHCP) o los DNS corporativos. 3. Probar con nslookup dominio servidor_dns. 4. Si el servidor DNS corporativo no responde, escalar a Infraestructura.', 1, 'ACTIVO', TRUE, '2026-03-22 00:00:00', '2026-03-22 00:00:00'),
(4, 'La VPN corporativa no conecta', 'El cliente VPN no establece el túnel desde casa.', 'Error de tiempo de espera o error 809; la conexión se queda en ''Conectando''.', 'Bloqueo de puertos en el router doméstico, certificado de cliente vencido o reloj del equipo desfasado.', '1. Verificar que haya internet sin VPN. 2. Sincronizar la hora de Windows. 3. Reiniciar el cliente VPN y volver a iniciar sesión. 4. Revisar vigencia del certificado del cliente. 5. Probar desde otra red (hotspot) para descartar bloqueo del proveedor; si funciona, el usuario debe habilitar IPsec/UDP 500 y 4500 en su router.', 1, 'ACTIVO', TRUE, '2026-03-23 00:00:00', '2026-03-23 00:00:00'),
(5, 'Lentitud de red por negociación de velocidad en cable', 'La red cableada va muy lenta.', 'Transferencias a 10 Mbps; el adaptador muestra 10 Mbps half duplex.', 'Negociación incorrecta de velocidad/dúplex entre el equipo y el switch antiguo.', 'Forzar 100 Mbps full duplex en el adaptador. (Procedimiento obsoleto tras la renovación de switches.)', 1, 'INACTIVO', TRUE, '2026-03-24 00:00:00', '2026-03-24 00:00:00'),
(6, 'El proxy bloquea un sitio web necesario para el trabajo', 'Un sitio legítimo aparece bloqueado por el proxy corporativo.', 'Página de bloqueo del proxy con categoría del sitio; otros sitios funcionan.', 'La categoría del sitio está restringida en la política de filtrado web.', '1. Confirmar la URL exacta y la justificación de negocio. 2. Registrar solicitud de excepción con aprobación del jefe inmediato. 3. Seguridad agrega la URL a la lista permitida. 4. Pedir al usuario limpiar caché del navegador y reintentar.', 1, 'ACTIVO', TRUE, '2026-03-25 00:00:00', '2026-03-25 00:00:00'),
(7, 'El equipo de escritorio no enciende', 'Al presionar el botón de encendido no hay respuesta.', 'Sin luces, sin ventiladores, sin pitidos.', 'Fuente de poder dañada, cable de energía desconectado o regleta apagada.', '1. Verificar regleta y cable de poder probando otro tomacorriente. 2. Revisar el interruptor trasero de la fuente. 3. Mantener presionado el botón 30 s sin corriente para descargar. 4. Si no enciende, reemplazar la fuente o solicitar equipo de respaldo mientras se tramita garantía.', 2, 'ACTIVO', TRUE, '2026-03-26 00:00:00', '2026-03-26 00:00:00'),
(8, 'Portátil se sobrecalienta y se apaga solo', 'El portátil se apaga sin aviso cuando está en uso intensivo.', 'Ventilador muy ruidoso, carcasa caliente, apagados durante videollamadas.', 'Acumulación de polvo en disipador o pasta térmica degradada.', '1. Verificar temperaturas con la herramienta del fabricante. 2. Usar el equipo sobre superficie dura. 3. Programar mantenimiento preventivo: limpieza de ventiladores y cambio de pasta térmica. 4. Actualizar BIOS si el fabricante publicó mejoras de gestión térmica.', 2, 'ACTIVO', TRUE, '2026-03-27 00:00:00', '2026-03-27 00:00:00'),
(9, 'Disco duro lento o con sectores dañados', 'El equipo tarda mucho en abrir archivos y se congela.', 'Uso de disco al 100%, ruidos en el disco, errores de lectura, SMART con advertencia.', 'Degradación física del disco mecánico.', '1. Respaldar inmediatamente la información del usuario. 2. Ejecutar chkdsk /f /r. 3. Revisar estado SMART. 4. Si hay advertencias, reemplazar por SSD y restaurar el respaldo.', 2, 'ACTIVO', TRUE, '2026-03-28 00:00:00', '2026-03-28 00:00:00'),
(10, 'Monitor externo no detectado', 'El segundo monitor queda en negro o sin señal.', 'Mensaje ''Sin señal''; Windows no lista la segunda pantalla.', 'Cable o adaptador defectuoso, entrada incorrecta en el monitor o controlador de video desactualizado.', '1. Verificar la entrada seleccionada en el monitor. 2. Cambiar cable o adaptador HDMI/USB-C. 3. Presionar Win+P y elegir ''Extender''. 4. Actualizar el controlador de video. 5. Probar el monitor en otro equipo para aislar la falla.', 2, 'ACTIVO', TRUE, '2026-03-29 00:00:00', '2026-03-29 00:00:00'),
(11, 'Aplicación de escritorio se cierra al iniciar por falta de componentes', 'Una aplicación se cierra inmediatamente después de abrirla.', 'Error de ejecución ''The application was unable to start correctly (0xc000007b)'' o falta de MSVCP140.dll / VCRUNTIME140.dll.', 'Faltan o están dañados los paquetes redistribuibles de Visual C++ o .NET requeridos por la aplicación.', '1. Revisar el Visor de eventos > Aplicación para identificar el módulo con error. 2. Instalar o reparar Microsoft Visual C++ Redistributable (x86 y x64) y la versión de .NET requerida. 3. Reinstalar la aplicación como administrador. 4. Reiniciar y validar.', 3, 'ACTIVO', TRUE, '2026-03-30 00:00:00', '2026-03-30 00:00:00'),
(12, 'Error de memoria insuficiente (Java heap space) en aplicación', 'Una aplicación Java falla al procesar archivos grandes.', 'Error de ejecución java.lang.OutOfMemoryError: Java heap space; la aplicación se congela y se cierra.', 'El parámetro de memoria máxima de la JVM (-Xmx) es insuficiente para la carga de trabajo.', '1. Confirmar el error en el log de la aplicación. 2. Aumentar -Xmx en el archivo de configuración o acceso directo (por ejemplo -Xmx2048m) sin superar el 50% de la RAM. 3. Cerrar otras aplicaciones pesadas. 4. Si persiste, reportar a Aplicaciones con el log para revisar fugas de memoria.', 3, 'ACTIVO', TRUE, '2026-03-31 00:00:00', '2026-03-31 00:00:00'),
(13, 'El ERP muestra error de conexión con la base de datos', 'El sistema ERP no carga datos.', 'Mensaje ''Timeout expired'' o ''No se pudo conectar con el servidor de base de datos'' al iniciar sesión.', 'Caída de conectividad con el servidor de base de datos, servicio detenido o cadena de conexión desactualizada tras migración.', '1. Verificar si el error afecta a uno o varios usuarios. 2. Probar conectividad al servidor (ping y telnet al puerto). 3. Si afecta a todos, escalar a Infraestructura para validar el servicio de base de datos. 4. Si afecta a uno, actualizar el archivo de configuración del cliente ERP con la cadena vigente.', 3, 'ACTIVO', TRUE, '2026-04-01 00:00:00', '2026-04-01 00:00:00'),
(14, 'Aplicación web interna muestra error 500 o página en blanco', 'Un portal web interno no carga correctamente.', 'Error HTTP 500, página en blanco o estilos rotos tras una actualización.', 'Caché del navegador con versiones antiguas de archivos o error en el despliegue del servidor.', '1. Recargar sin caché (Ctrl+F5) y probar en ventana privada. 2. Borrar caché y cookies del sitio. 3. Si el error persiste para varios usuarios, escalar a Aplicaciones con hora, URL y captura del error para revisar logs del servidor.', 3, 'ACTIVO', TRUE, '2026-04-02 00:00:00', '2026-04-02 00:00:00'),
(15, 'Macros de Excel bloqueadas', 'Las macros de un libro de Excel no se ejecutan.', 'Barra roja ''Microsoft ha bloqueado la ejecución de macros''.', 'Política de seguridad de Office para archivos descargados de internet.', 'Desbloquear el archivo en Propiedades. (Reemplazado por la política de ubicaciones de confianza.)', 3, 'INACTIVO', TRUE, '2026-04-03 00:00:00', '2026-04-03 00:00:00'),
(16, 'Las actualizaciones de Windows fallan con error 0x80070002', 'Windows Update no instala actualizaciones.', 'Error 0x80070002 o 0x8024402f; actualizaciones pendientes por semanas.', 'Archivos de la carpeta SoftwareDistribution dañados o servicio de actualización detenido.', '1. Ejecutar el solucionador de problemas de Windows Update. 2. Detener los servicios wuauserv y bits, renombrar C:\Windows\SoftwareDistribution y reiniciar los servicios. 3. Ejecutar sfc /scannow y DISM /Online /Cleanup-Image /RestoreHealth. 4. Reintentar la actualización.', 4, 'ACTIVO', TRUE, '2026-04-04 00:00:00', '2026-04-04 00:00:00'),
(17, 'Pantalla azul después de instalar un controlador', 'El equipo muestra pantalla azul al iniciar.', 'BSOD con códigos como DRIVER_IRQL_NOT_LESS_OR_EQUAL; reinicios en bucle.', 'Controlador incompatible instalado recientemente.', '1. Iniciar en modo seguro (reparación automática > opciones avanzadas). 2. Desinstalar el controlador reciente o usar Restaurar sistema. 3. Instalar la versión certificada del fabricante. 4. Revisar el volcado de memoria si se repite.', 4, 'ACTIVO', TRUE, '2026-04-05 00:00:00', '2026-04-05 00:00:00'),
(18, 'Equipo muy lento al iniciar sesión', 'El inicio de Windows tarda varios minutos.', 'Escritorio sin responder tras iniciar sesión; uso alto de CPU y disco al arrancar.', 'Exceso de programas de inicio, poco espacio en disco o falta de memoria RAM.', '1. Deshabilitar programas innecesarios en Administrador de tareas > Inicio. 2. Liberar espacio (mínimo 15% libre) con Liberador de espacio. 3. Verificar que el antivirus no esté en análisis completo al inicio. 4. Si la RAM es menor a 8 GB, solicitar ampliación.', 4, 'ACTIVO', TRUE, '2026-04-06 00:00:00', '2026-04-06 00:00:00'),
(19, 'El usuario inicia sesión con un perfil temporal', 'Al iniciar sesión el escritorio aparece vacío.', 'Mensaje ''Se inició sesión con un perfil temporal''; no aparecen archivos ni configuraciones.', 'Perfil de usuario dañado en el registro (clave .bak en ProfileList).', '1. Respaldar datos de C:\Users\usuario. 2. En regedit, HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList, corregir la clave duplicada .bak. 3. Reiniciar y validar. 4. Si no funciona, crear perfil nuevo y migrar los datos.', 4, 'ACTIVO', TRUE, '2026-04-07 00:00:00', '2026-04-07 00:00:00'),
(20, 'Outlook no sincroniza y pide contraseña repetidamente', 'Outlook no recibe correos nuevos.', 'Ventana de credenciales que reaparece; estado ''Desconectado'' o ''Intentando conectar''.', 'Credenciales almacenadas desactualizadas tras cambio de contraseña o perfil de Outlook dañado.', '1. Eliminar las credenciales de Office en el Administrador de credenciales de Windows. 2. Cerrar Outlook y abrirlo de nuevo para autenticar con la contraseña actual. 3. Si persiste, crear un nuevo perfil de Outlook desde Panel de control > Correo.', 5, 'ACTIVO', TRUE, '2026-04-08 00:00:00', '2026-04-08 00:00:00'),
(21, 'Buzón de correo lleno', 'El usuario no puede enviar ni recibir correos.', 'Aviso ''Su buzón ha superado el límite''; correos rebotados.', 'Se alcanzó la cuota de almacenamiento del buzón.', '1. Vaciar Elementos eliminados y Correo no deseado. 2. Ordenar por tamaño y archivar adjuntos grandes en OneDrive. 3. Habilitar archivo en línea si la licencia lo permite. 4. Solicitar aumento de cuota solo con justificación.', 5, 'ACTIVO', TRUE, '2026-04-09 00:00:00', '2026-04-09 00:00:00'),
(22, 'Microsoft Teams sin audio o sin micrófono en reuniones', 'Los participantes no escuchan al usuario o el usuario no escucha.', 'Micrófono silenciado o no detectado en Teams; otras aplicaciones sí funcionan.', 'Dispositivo de audio incorrecto seleccionado en Teams o permisos de micrófono deshabilitados en Windows.', '1. En Teams > Configuración > Dispositivos, seleccionar el micrófono y altavoz correctos y hacer llamada de prueba. 2. En Windows > Privacidad > Micrófono, permitir acceso a las aplicaciones. 3. Limpiar la caché de Teams y reiniciar. 4. Actualizar el controlador de audio o probar con otra diadema.', 5, 'ACTIVO', TRUE, '2026-04-10 00:00:00', '2026-04-10 00:00:00'),
(23, 'Reporte de correo de phishing', 'Un usuario recibió un correo sospechoso que solicita credenciales.', 'Remitente desconocido o suplantado, enlaces a sitios falsos, urgencia para iniciar sesión.', 'Campaña de phishing dirigida a la organización.', '1. No hacer clic en enlaces ni abrir adjuntos. 2. Reportar con el botón ''Reportar phishing'' o reenviar a seguridad. 3. Si el usuario ingresó credenciales, cambiar contraseña de inmediato y revocar sesiones. 4. Seguridad bloquea el remitente y las URL y busca el mismo correo en otros buzones.', 6, 'ACTIVO', TRUE, '2026-04-11 00:00:00', '2026-04-11 00:00:00'),
(24, 'El antivirus detectó malware en el equipo', 'Alerta del antivirus sobre un archivo malicioso.', 'Notificación de amenaza detectada, archivo en cuarentena, equipo lento o ventanas emergentes.', 'Descarga de archivo infectado o dispositivo USB comprometido.', '1. Desconectar el equipo de la red si hay comportamiento anómalo. 2. Verificar que el archivo esté en cuarentena. 3. Ejecutar análisis completo actualizado. 4. Revisar en la consola de seguridad si hay más equipos afectados. 5. Si el análisis no limpia, reinstalar el sistema desde imagen corporativa.', 6, 'ACTIVO', TRUE, '2026-04-12 00:00:00', '2026-04-12 00:00:00'),
(25, 'Certificado SSL vencido en sitio interno', 'El navegador advierte que la conexión no es privada.', 'NET::ERR_CERT_DATE_INVALID en un portal interno.', 'El certificado del servidor expiró.', 'Borrador: renovar el certificado con la CA interna y desplegarlo en el servidor web.', 6, 'BORRADOR', FALSE, '2026-04-13 00:00:00', '2026-04-13 00:00:00'),
(26, 'Cola de impresión atascada', 'Los documentos no salen de la impresora.', 'Trabajos en estado ''Error'' o ''En cola'' que no avanzan; la impresora está encendida.', 'Trabajo de impresión dañado bloquea la cola del servicio Spooler.', '1. Cancelar todos los documentos de la cola. 2. Detener el servicio ''Cola de impresión'' (spooler), borrar C:\Windows\System32\spool\PRINTERS y reiniciar el servicio. 3. Apagar y encender la impresora. 4. Enviar una página de prueba.', 7, 'ACTIVO', TRUE, '2026-04-14 00:00:00', '2026-04-14 00:00:00'),
(27, 'El escáner no envía documentos al correo', 'La multifuncional escanea pero el correo no llega.', 'Error de envío SMTP en el panel de la impresora.', 'Configuración SMTP desactualizada.', 'Borrador: actualizar servidor SMTP y credenciales en la multifuncional.', 7, 'BORRADOR', FALSE, '2026-04-15 00:00:00', '2026-04-15 00:00:00'),
(28, 'Cuenta de usuario bloqueada por intentos fallidos', 'El usuario no puede iniciar sesión en Windows ni en aplicaciones.', 'Mensaje ''La cuenta de referencia está bloqueada''.', 'Varios intentos con contraseña incorrecta, frecuentemente por credenciales antiguas guardadas en un celular o unidad de red.', '1. Verificar la identidad del usuario según el protocolo. 2. Desbloquear la cuenta en Active Directory. 3. Identificar el origen de los intentos (registro de eventos 4740). 4. Pedir al usuario actualizar la contraseña en celular, unidades mapeadas y credenciales guardadas.', 8, 'ACTIVO', TRUE, '2026-04-16 00:00:00', '2026-04-16 00:00:00'),
(29, 'No llega el código MFA o se cambió de celular', 'El usuario no puede completar la autenticación multifactor.', 'No llega la notificación de Authenticator o el usuario cambió de teléfono.', 'El método MFA registrado ya no está disponible en el dispositivo.', '1. Verificar identidad del usuario. 2. Restablecer los métodos MFA en el portal de administración. 3. Guiar al usuario para registrar de nuevo Microsoft Authenticator. 4. Validar inicio de sesión de prueba.', 8, 'ACTIVO', TRUE, '2026-04-17 00:00:00', '2026-04-17 00:00:00'),
(30, 'Sin permisos para acceder a una carpeta compartida', 'El usuario recibe acceso denegado a una carpeta de red.', 'Mensaje ''No tiene permiso para obtener acceso''; otros compañeros sí acceden.', 'El usuario no pertenece al grupo de seguridad que tiene permisos sobre la carpeta.', '1. Confirmar la ruta y el nivel de acceso requerido. 2. Obtener aprobación del dueño de la información. 3. Agregar al usuario al grupo de seguridad correspondiente. 4. Pedir cerrar sesión e iniciar de nuevo para aplicar la membresía.', 8, 'ACTIVO', TRUE, '2026-04-18 00:00:00', '2026-04-18 00:00:00');
INSERT INTO incidente (id, titulo, descripcion, categoria_id, prioridad, estado, fecha_creacion, fecha_actualizacion, fecha_resolucion, usuario_id) VALUES
(1, 'Equipo muy lento al iniciar sesión #001', 'El equipo tarda más de 5 minutos en mostrar el escritorio.', 4, 'MEDIA', 'RESUELTO', '2026-05-19 15:42:00', '2026-05-21 05:32:24', '2026-05-21 05:32:24', 6),
(2, 'Correo sospechoso recibido #002', 'Recibí un correo que pide actualizar mi contraseña con un enlace extraño.', 6, 'MEDIA', 'CERRADO', '2026-05-19 12:16:00', '2026-05-24 07:28:00', '2026-05-21 07:28:00', 10),
(3, 'Escáner no envía al correo #003', 'La multifuncional escanea pero el correo nunca llega.', 7, 'MEDIA', 'RESUELTO', '2026-05-20 15:03:00', '2026-05-20 22:50:24', '2026-05-20 22:50:24', 12),
(4, 'No llega código MFA #004', 'Cambié de celular y no puedo aprobar la autenticación multifactor.', 8, 'ALTA', 'CERRADO', '2026-05-19 15:35:00', '2026-05-21 23:51:48', '2026-05-19 23:51:48', 11),
(5, 'Escáner no envía al correo #005', 'La multifuncional escanea pero el correo nunca llega.', 7, 'BAJA', 'CERRADO', '2026-05-21 08:57:00', '2026-05-28 07:55:12', '2026-05-26 07:55:12', 12),
(6, 'Equipo muy lento al iniciar sesión #006', 'El equipo tarda más de 5 minutos en mostrar el escritorio.', 4, 'BAJA', 'CERRADO', '2026-05-21 20:01:00', '2026-05-30 21:10:36', '2026-05-28 21:10:36', 12),
(7, 'Instalación de software solicitado #007', 'Se requiere instalar el software de diseño autorizado en el equipo del área.', 3, 'ALTA', 'CERRADO', '2026-05-21 18:06:00', '2026-05-25 07:26:24', '2026-05-22 07:26:24', 8),
(8, 'Outlook pide contraseña #008', 'Outlook pide la contraseña todo el tiempo y no llegan correos nuevos.', 5, 'BAJA', 'EN_PROGRESO', '2026-05-19 13:22:00', '2026-05-19 16:22:00', NULL, 2),
(9, 'Instalación de software solicitado #009', 'Se requiere instalar el software de diseño autorizado en el equipo del área.', 3, 'BAJA', 'RESUELTO', '2026-05-20 08:34:00', '2026-05-24 19:08:12', '2026-05-24 19:08:12', 8),
(10, 'No abren páginas por nombre #010', 'Puedo hacer ping a una IP pero las páginas web no cargan por nombre, aparece error DNS.', 1, 'BAJA', 'CERRADO', '2026-05-18 14:08:00', '2026-05-23 12:27:12', '2026-05-20 12:27:12', 5),
(11, 'Computador no enciende #011', 'El equipo de escritorio no enciende, no prenden luces ni ventiladores.', 2, 'MEDIA', 'CERRADO', '2026-05-29 08:33:00', '2026-06-01 08:56:24', '2026-05-31 08:56:24', 12),
(12, 'Alerta de antivirus #012', 'El antivirus detectó una amenaza en un archivo descargado y lo puso en cuarentena.', 6, 'MEDIA', 'RESUELTO', '2026-05-28 08:27:00', '2026-05-29 11:32:24', '2026-05-29 11:32:24', 11),
(13, 'Red lenta en el piso 3 #013', 'La navegación y las carpetas compartidas están muy lentas en todo el piso.', 1, 'CRITICA', 'CERRADO', '2026-05-28 10:53:00', '2026-05-30 11:43:24', '2026-05-28 11:43:24', 1),
